scwin.vScrenID = "ULDINS16500.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : 온실가스배출권 목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    // 코드부여일 체크
    //if (compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
    //	return false;	
    //}

    dts_detail.removeAll();

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS16500_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.prod.select.listStdCdGreenhouseInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.value + "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue() + "&{P}ALLW_OFS_TP_CD=" + $c.stf.getObjectValue(cmb_pALLW_OFS_TP_CD); //
    //"&{P}SDATE="  +  edt_SDATE.text + 
    //"&{P}EDATE="  + edt_EDATE.text ;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 온실가스배출권 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    dts_detail.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS16500_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdetn.select.readstdcdGreenhouseInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};
scwin.clickRdoTp = function() {
    var BAS_IDX_CNTR_TP_CD = $c.stf.getObjectValue(rdo_BAS_IDX_CNTR_TP);
    if (BAS_IDX_CNTR_TP_CD != "99") {
        $c.stf.setObjectValue(txb_BAS_IDX_CNTR_TP_MISC, "");
        txb_BAS_IDX_CNTR_TP_MISC.setDisabled(true);
        txb_BAS_IDX_CNTR_TP_MISC.style.backgroundColor = '#b9d4f7';
    } else {
        txb_BAS_IDX_CNTR_TP_MISC.setDisabled(false);
        txb_BAS_IDX_CNTR_TP_MISC.style.backgroundColor = 'white';
    }
};
scwin.clickRdoClss = function() {
    var BAS_IDX_CLSS_CD = $c.stf.getObjectValue(rdo_BAS_IDX_CLSS);
    if (BAS_IDX_CLSS_CD != "99") {
        $c.stf.setObjectValue(txb_BAS_IDX_CLSS_MISC, "");
        txb_BAS_IDX_CLSS_MISC.setDisabled(true);
        txb_BAS_IDX_CLSS_MISC.style.backgroundColor = '#b9d4f7';
    } else {
        txb_BAS_IDX_CLSS_MISC.setDisabled(false);
        txb_BAS_IDX_CLSS_MISC.style.backgroundColor = 'white';
    }
};



/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
        txb_ISU_NM.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_BAS_IDX_CNTR_TP) == "99" && (txb_BAS_IDX_CNTR_TP_MISC.getValue().indexOf(" ") == "" || $c.stf.getObjectValue(txb_BAS_IDX_CNTR_TP_MISC) == "")) {
        $c.win.alert("기초지수국가구분이 기타일 경우에는 내용을 입력해 주시기 바랍니다.");
        txb_BAS_IDX_CNTR_TP_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_IDX_CNTR_TP_MISC, 40, "기초지수 국가 구분 기타")) {
        txb_BAS_IDX_CNTR_TP_MISC.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_BAS_IDX_CLSS) == "99" && (txb_BAS_IDX_CLSS_MISC.getValue().indexOf(" ") == "" || $c.stf.getObjectValue(txb_BAS_IDX_CLSS_MISC) == "")) {
        $c.win.alert("기초지수분류가 기타일 경우에는 내용을 입력해 주시기 바랍니다.");
        txb_BAS_IDX_CLSS_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_IDX_CLSS_MISC, 40, "기초지수분류 기타")) {
        txb_BAS_IDX_CLSS_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_MEMO_CONTN, 200, "담당자메모")) {
        txa_MEMO_CONTN.focus();
        return false;
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};



/********************************************** 
 * 함수명   : ins_modify
 * 설명       : etn 표준코드  수정한다.
 ***********************************************/
scwin.ins_modify = function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRUDSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_modify.Action = "/StdCdEtnInfoAction.do?method=modifyStdCdEtnInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInputMaster=dts_detail)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       : etn 삭제처리한다.
 ***********************************************/
scwin.ins_remove = function() {

    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_Delete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_remove.Action = "/StdCdEtnInfoAction.do?method=removeStdCdEtnInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_remove.KeyName = "toinb_dataid4";
    trs_remove.KeyValue = "JSP(I:pInput=dts_Delete)";
    trs_remove.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_remove.Post();
};



/*
 * 한글 입력불가
 */
scwin.fn_ChkHan = function(Obj) {
    var limit_char = /[ㄱ-ㅎ|ㅏ-ㅣ|가-힝]/g;
    var numstr = $c.stf.getObjectValue(Obj);
    if (limit_char.test(numstr)) {
        $c.win.alert("한글은 입력할 수 없습니다.");
        Obj.focus();
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    //PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_4);
    //PanelToGroupBox(panel_6);

    fn_CtrlBtn_temp("no_data");
    $c.stf.showObj(txb_DEL_RSN, false);
    $c.stf.showObj(txb_STD_CD_APPL_ID, false);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (row == 0) return;
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    scwin.ins_detail(STD_CD);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.trs_modify_OnFail = function() {
    alert_tr_error(trs_modify);
};
scwin.trs_modify_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.ins_search();
    scwin.ins_detail(txb_STD_CD.getValue());
};
scwin.trs_remove_OnFail = function() {
    alert_tr_error(trs_remove);
};
scwin.trs_remove_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.ins_search();
    scwin.ins_detail("");
};
scwin.trs_pwd_OnFail = function() {
    alert_tr_error(trs_pwd);
};
scwin.trs_pwd_OnSuccess = function() {
    $c.win.alert("비밀번호 초기화 완료 후 메일 발송 완료 하였습니다.");
};
scwin.trs_Delete_OnFail = function() {
    alert_tr_error(trs_Delete);
};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
