    */
};
scwin.txb_ISU_ENG_ABBRV_onblur = function() {
    scwin.fn_ChkHan(txb_ISU_ENG_ABBRV);
};
scwin.txb_ISU_ENG_NM_onblur = function() {
    scwin.fn_ChkHan(txb_ISU_ENG_NM);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.txb_pSTD_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pSTD_CD.value == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_pISU_KOR_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISU_KOR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.cmb_pALLW_OFS_TP_CD_OnSelChange = function() {
    scwin.ins_search();
};
